-- 1. The table
create table public.notes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  title text not null,
  content text,
  created_at timestamptz not null default now()
);

-- 2. The lock. This line is the one almost everyone forgets.
alter table public.notes enable row level security;

-- 3. The four rules: view, create, change, delete.
create policy "each user sees their own notes"
  on public.notes for select
  to authenticated
  using ( auth.uid() = user_id );

create policy "each user creates their own notes"
  on public.notes for insert
  to authenticated
  with check ( auth.uid() = user_id );

create policy "each user changes their own notes"
  on public.notes for update
  to authenticated
  using ( auth.uid() = user_id )
  with check ( auth.uid() = user_id );

create policy "each user deletes their own notes"
  on public.notes for delete
  to authenticated
  using ( auth.uid() = user_id );

-- 4. So searching by user doesn't drag once you have thousands of rows.
create index notes_user_id_idx on public.notes (user_id);

# file: .env.local   (this file does NOT get uploaded to GitHub)
VITE_SUPABASE_URL=https://YOUR-PROJECT.supabase.co
VITE_SUPABASE_ANON_KEY=PASTE_THE_PUBLIC_KEY_HERE

// file: src/supabase.js
import { createClient } from '@supabase/supabase-js'

// The public key can be seen in the browser: that's its job.
// What protects the data are the policies, not this key.
export const supabase = createClient(
  import.meta.env.VITE_SUPABASE_URL,
  import.meta.env.VITE_SUPABASE_ANON_KEY
)

// Read the notes of the currently logged-in user.
// With the policies in place, you don't need to filter by user_id:
// the database no longer shows anyone else's anyway.
const { data, error } = await supabase
  .from('notes')
  .select('id, title, content, created_at')
  .order('created_at', { ascending: false })

if (error) {
  console.log('Supabase error:', error.message)
} else if (data.length === 0) {
  console.log('Zero rows. Either there is no data, or the read policy is missing.')
}
